-- Views and materialized views in public
-- Generated by scripts/schema-snapshot.mjs from project heuhqqoxyggawuckxocp. Do not edit by hand.

create or replace view public.challenge_group_totals with (security_invoker=true) as
 SELECT s.challenge_id,
    gm.group_id,
    count(DISTINCT s.creator_id) AS creators,
    count(s.id) AS entries,
    COALESCE(sum(COALESCE(s.logged_views, 0)), 0::bigint) AS views,
    COALESCE(max(COALESCE(s.logged_views, 0)), 0) AS best_video,
    max(s.submitted_at) AS last_entry_at
   FROM submissions s
     LEFT JOIN challenge_group_members gm ON gm.challenge_id = s.challenge_id AND gm.creator_id = s.creator_id
  GROUP BY s.challenge_id, gm.group_id;

create or replace view public.challenge_history_metrics with (security_invoker=true) as
 SELECT id,
    community_id,
    country_code,
    ref,
    title,
    seq,
    starts_at,
    ends_at,
    cadence,
    cohort,
    prize_type,
    content_type,
    objective,
    status,
    prize_total,
    prize_currency,
    winners,
    total_views,
    creators,
    posts,
    notes,
    challenge_id,
    source,
    created_at,
    updated_at,
    created_by,
        CASE
            WHEN total_views > 0 THEN round(prize_total / (total_views::numeric / 1000.0), 2)
            ELSE NULL::numeric
        END AS cpm,
    round(prize_total / NULLIF(posts, 0)::numeric, 2) AS cost_per_post,
    round(prize_total / NULLIF(creators, 0)::numeric, 2) AS cost_per_creator,
    round(posts::numeric / NULLIF(creators, 0)::numeric, 1) AS posts_per_creator,
    total_views / NULLIF(posts, 0) AS views_per_post,
    total_views / NULLIF(creators, 0) AS views_per_creator,
    GREATEST(1, ends_at - starts_at) AS days
   FROM challenge_history h;

create or replace view public.challenge_standings with (security_invoker=true) as
 SELECT challenge_id,
    community_id,
    creator_id,
    sum(points) AS points,
    count(*) FILTER (WHERE NOT is_auto) AS manual_awards
   FROM point_awards a
  GROUP BY challenge_id, community_id, creator_id;

create or replace view public.community_standings with (security_invoker=true) as
 SELECT community_id,
    creator_id,
    sum(points) AS points
   FROM point_awards a
  GROUP BY community_id, creator_id;

create or replace view public.network_standings with (security_invoker=true) as
 SELECT creator_id,
    sum(points) AS points,
    count(DISTINCT community_id) AS markets
   FROM point_awards a
  GROUP BY creator_id;

create or replace view public.vip_members_live as
 SELECT profile_id,
    programme_id,
    status,
    cpm,
    monthly_cap,
    target_videos,
    target_views,
    joined_on,
    left_on,
    source,
    terms_accepted_at,
    terms_version,
    notes,
    created_by,
    created_at,
    milestone_notified,
    auto_home,
    headline,
    accent,
    own_goal_views,
    show_on_map,
    rate_review_on,
    tiers,
    monthly_fee,
    fee_min_videos,
    bonuses_on,
    auto_payout,
    join_notice_pending
   FROM vip_members m
  WHERE NOT (EXISTS ( SELECT 1
           FROM profiles p
          WHERE p.id = m.profile_id AND (COALESCE(p.is_test, false) OR COALESCE(p.is_sandbox, false) OR NOT (COALESCE(p.onboarded, false) AND p.status = 'active'::text))));
